using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Underwater.Editor {
public static class DolphinMotionIntegration {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity";const string Output="Renders/DolphinMotion/";
 public static void Inspect(){EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);var sb=new System.Text.StringBuilder();foreach(var life in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(l=>l.kind=="Dolphin")){var w=life.GetComponent<WreckCreature>();sb.AppendLine(life.name+" pos="+life.transform.position+" rot="+life.transform.eulerAngles+" scale="+life.transform.lossyScale+" habitat="+w.habitatCenter+" phase="+w.phase+" radius="+life.GetComponent<ReefSphereBody>().radius+" clearance="+life.GetComponent<ReefAnimalClearance>().animatedBody);foreach(var t in life.GetComponentsInChildren<Transform>())sb.AppendLine(t.name+" components="+string.Join(",",t.GetComponents<Component>().Select(c=>c?c.GetType().Name:"missing")));}File.WriteAllText(Output+"Before.txt",sb.ToString());Debug.Log("DOLPHINS_INSPECTED");}
 static WreckCreature[] Actors()=>UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None).Where(w=>w.species==WreckCreature.Species.Dolphin).OrderBy(w=>w.name).ToArray();
 public static void Run(){
 var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);var actors=Actors();if(actors.Length!=3)throw new Exception("Expected three dolphins");var otherActors=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(l=>l.kind!="Dolphin").ToDictionary(l=>l,l=>EditorJsonUtility.ToJson(l)+EditorJsonUtility.ToJson(l.transform));
 var drivers=new System.Collections.Generic.List<DolphinSwimController>();var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UnderwaterArt/MarineRefresh/Dolphin/Dolphin.fbx");var neutral=prefab.GetComponentsInChildren<Transform>().GroupBy(t=>t.name).ToDictionary(g=>g.Key,g=>g.First());
 for(int n=0;n<actors.Length;n++){
  var actor=actors[n];var originalPose=actor.transform.localToWorldMatrix;var oldColliders=actor.GetComponentsInChildren<Collider>(true).ToDictionary(c=>c,c=>EditorJsonUtility.ToJson(c));var player=actor.GetComponentInChildren<Animation>();var legacy=player.GetComponent<ReefImportedAnimation>();if(legacy)legacy.enabled=false;player.enabled=false;player.playAutomatically=false;foreach(var t in player.GetComponentsInChildren<Transform>()){if(t==player.transform)continue;if(neutral.TryGetValue(t.name,out var source)){t.localPosition=source.localPosition;t.localRotation=source.localRotation;t.localScale=source.localScale;}}
  var driver=actor.GetComponent<DolphinSwimController>();if(!driver)driver=actor.gameObject.AddComponent<DolphinSwimController>();driver.podIndex=n;driver.animationPlayer=player;driver.skin=player.GetComponentInChildren<SkinnedMeshRenderer>();driver.referenceSpeed=driver.bodyLength*.28f;driver.minimumSeparation=3.9f;drivers.Add(driver);
  if(actor.transform.localToWorldMatrix!=originalPose||oldColliders.Any(p=>EditorJsonUtility.ToJson(p.Key)!=p.Value))throw new Exception("Dolphin placement or touch colliders changed");
 }
 PrepareEyes(drivers.ToArray());foreach(var d in drivers)d.pod=drivers.ToArray();
 foreach(var driver in drivers){driver.Initialize();var skin=driver.skin;bool first=true;Bounds local=default,whole=default;for(int f=0;f<48;f++)foreach(float turn in new[]{-1f,0f,1f})foreach(float blink in new[]{0f,1f}){
  driver.ApplyPose(f/48f*Mathf.PI*2,1,turn,blink,f%2==0?-10:-5,driver.transform.position+driver.transform.forward*2+driver.transform.right*(f%2==0?-1:1));foreach(var world in OctopusRepairValidation.Points(skin)){var a=driver.transform.InverseTransformPoint(world);var b=(skin.rootBone?skin.rootBone:skin.transform).InverseTransformPoint(world);if(first){whole=new Bounds(a,Vector3.zero);local=new Bounds(b,Vector3.zero);first=false;}else {whole.Encapsulate(a);local.Encapsulate(b);}}}
  whole.Expand(.05f);local.Expand(.05f);driver.GetComponent<ReefAnimalClearance>().animatedBody=whole;skin.localBounds=local;skin.updateWhenOffscreen=false;driver.ApplyPose(0,0,0,0,-10);
 }
 foreach(var pair in otherActors)if(!pair.Key||EditorJsonUtility.ToJson(pair.Key)+EditorJsonUtility.ToJson(pair.Key.transform)!=pair.Value)throw new Exception("Unrelated creature changed");AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);Capture();Validate();Debug.Log("DOLPHIN_MOVEMENT_AND_POSE_INTEGRATED");
 }
 public static void Validate(){
 EditorSceneManager.OpenScene(Scene);var actors=Actors();var drivers=actors.Select(a=>a.GetComponent<DolphinSwimController>()).ToArray();var distance=new float[actors.Length];var prev=actors.Select(a=>a.transform.position).ToArray();float minGap=float.MaxValue,minAlignment=1,maxTurn=0,maxStep=0,minFloor=float.MaxValue;var modes=new System.Collections.Generic.HashSet<string>();
 for(int f=0;f<2400;f++){
  for(int i=0;i<actors.Length;i++){var a=actors[i];var start=a.transform.position;var oldForward=a.transform.forward;a.Step(.05f);var d=drivers[i];a.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();var delta=a.transform.position-start;distance[i]+=delta.magnitude;maxStep=Mathf.Max(maxStep,delta.magnitude);maxTurn=Mathf.Max(maxTurn,Vector3.Angle(oldForward,a.transform.forward)/.05f);modes.Add(d.Mode.ToString());if(!a.GetComponent<ReefSphereBody>().Clear(a.transform.position))throw new Exception("Dolphin overlaps reef at frame "+f+" "+a.name);if(delta.sqrMagnitude>.000001f)minAlignment=Mathf.Min(minAlignment,Vector3.Dot(delta.normalized,a.transform.forward));if(!a.GetComponent<ReefAnimalClearance>().RequiredHeight(a.transform.position,a.transform.rotation,out var h))throw new Exception("Dolphin outside seabed bounds");minFloor=Mathf.Min(minFloor,a.transform.position.y-h);}
  for(int i=0;i<actors.Length;i++)for(int j=i+1;j<actors.Length;j++)minGap=Mathf.Min(minGap,Vector3.Distance(actors[i].transform.position,actors[j].transform.position));
 }
 if(distance.Any(d=>d<12)||minGap<2.7f||maxStep>.08f||maxTurn>36||minAlignment<-.05f)throw new Exception("Dolphin patrol failure: distance="+string.Join(",",distance)+" minGap="+minGap+" step="+maxStep+" turn="+maxTurn+" alignment="+minAlignment+" modes="+string.Join(",",modes));
 var report=new System.Text.StringBuilder();report.AppendLine("120-second three-dolphin simulation: travel="+string.Join(", ",distance.Select(x=>x.ToString("F2")))+" m; min separation="+minGap+" m; max frame step="+maxStep+" m; max turn="+maxTurn+" deg/sec; min forward alignment="+minAlignment+"; min seabed clearance="+minFloor+" m; modes="+string.Join(",",modes));
 EditorSceneManager.OpenScene(Scene);var source=Actors()[0];var driver=source.GetComponent<DolphinSwimController>();driver.Initialize();for(int i=0;i<100;i++)driver.StepVisual(.05f,.3f,0);float slow=driver.StrokeRate;for(int i=0;i<100;i++)driver.StepVisual(.05f,1,0);float fast=driver.StrokeRate;for(int i=0;i<100;i++)driver.StepVisual(.05f,0,0);float stopped=driver.StrokePhase;for(int i=0;i<20;i++)driver.StepVisual(.05f,0,0);if(fast<slow+.15f||driver.StrokePhase-stopped>.001f||driver.Effort>.001f)throw new Exception("Stroke does not follow travel speed");report.AppendLine("Actual-speed stroke sync: slow="+slow+" fast="+fast+" stopped tail phase delta="+(driver.StrokePhase-stopped));
 var bones=driver.animationPlayer.GetComponentsInChildren<Transform>();var positions=bones.Select(t=>t.localPosition).ToArray();var scales=bones.Select(t=>t.localScale).ToArray();driver.ApplyPose(0,0,0,0,-10);var first=OctopusRepairValidation.Points(driver.skin);driver.ApplyPose(Mathf.PI/2,1,1,1,-5,driver.transform.position+driver.transform.forward*2+driver.transform.right);var second=OctopusRepairValidation.Points(driver.skin);float deformation=first.Zip(second,(a,b)=>(a-b).magnitude).Max();if(deformation<.05f)throw new Exception("Body deformation missing");for(int i=0;i<bones.Length;i++)if((positions[i]-bones[i].localPosition).magnitude>.00001f||(scales[i]-bones[i].localScale).magnitude>.00001f)throw new Exception("Dolphin bone stretched");
 foreach(string name in new[]{"Kluv","eye L","eye R","eyelish_up L","eyelish_down R","FLIPPER_L02","TALE01"})if(!bones.Any(b=>b.name==name))throw new Exception("Anatomical bone missing: "+name);report.AppendLine("Full-body/tail/fin/eye/eyelid/jaw rig exercised; max vertex deformation="+deformation+" m; local bone lengths/scales unchanged.");
 driver.ApplyPose(0,0,0,0,-10);var open=OctopusRepairValidation.Points(driver.skin);driver.skin.SetBlendShapeWeight(0,100);driver.skin.SetBlendShapeWeight(1,100);var closed=OctopusRepairValidation.Points(driver.skin);float blinkDeformation=open.Zip(closed,(a,b)=>(a-b).magnitude).Max();if(blinkDeformation<.005f)throw new Exception("Blink shapes do not close eyes: "+blinkDeformation);report.AppendLine("Blink geometry max closure displacement="+blinkDeformation+" m; both eye shapes present.");
 File.WriteAllText(Output+"Validation.txt",report.ToString());EditorSceneManager.OpenScene(Scene);Debug.Log("DOLPHIN_SYNC_VALIDATED\n"+report);
 }
 public static void Capture(){EditorSceneManager.OpenScene(Scene);var actor=Actors()[0];var d=actor.GetComponent<DolphinSwimController>();d.Initialize();d.ApplyPose(.6f,.8f,0,0,-10,actor.transform.position+actor.transform.right*2);var cam=Camera.main;var optics=cam.GetComponent<ReefOptics>();if(optics)optics.enabled=false;var center=d.skin.bounds.center;cam.transform.position=center+actor.transform.right*4+Vector3.up*.3f;cam.transform.LookAt(center);cam.fieldOfView=45;ReefCorrectionAudit.Capture(cam,Output+"Body.png");var eye=d.animationPlayer.GetComponentsInChildren<Transform>().First(t=>t.name=="eye L");cam.transform.position=eye.position+actor.transform.right*1.5f+actor.transform.forward*.5f;cam.transform.LookAt(eye.position+actor.transform.forward*.2f);cam.fieldOfView=42;CapturePosed(cam,d.skin,Output+"FaceOpen.png");d.ApplyPose(.6f,.8f,0,1,-6,actor.transform.position+actor.transform.right*2);CapturePosed(cam,d.skin,Output+"FaceBlink.png");}
 static void PrepareEyes(DolphinSwimController[] drivers){
 const string folder="Assets/UnderwaterArt/DolphinMotion/";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var first=drivers[0];var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UnderwaterArt/MarineRefresh/Dolphin/Dolphin.fbx");var mesh=UnityEngine.Object.Instantiate(prefab.GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh);mesh.name="Dolphin anatomy with natural eyes and blink shapes";mesh.ClearBlendShapes();var weights=mesh.boneWeights;var eyeIndices=first.skin.bones.Select((b,i)=>new{b,i}).Where(x=>x.b.name=="eye L"||x.b.name=="eye R").ToDictionary(x=>x.b.name,x=>x.i);Func<BoneWeight,int,float> weight=(w,i)=>(w.boneIndex0==i?w.weight0:0)+(w.boneIndex1==i?w.weight1:0)+(w.boneIndex2==i?w.weight2:0)+(w.boneIndex3==i?w.weight3:0);
 var body=new System.Collections.Generic.List<int>();var eyes=new System.Collections.Generic.List<int>();var triangles=mesh.triangles;for(int i=0;i<triangles.Length;i+=3){float sum=0;for(int j=0;j<3;j++)foreach(var idx in eyeIndices.Values)sum+=weight(weights[triangles[i+j]],idx);var dest=sum>1.65f?eyes:body;dest.AddRange(new[]{triangles[i],triangles[i+1],triangles[i+2]});}if(eyes.Count<60)throw new Exception("Eye surface identification failed");mesh.subMeshCount=2;mesh.SetTriangles(body,0);mesh.SetTriangles(eyes,1);
 var original=first.skin.sharedMesh;first.skin.sharedMesh=mesh;var points=OctopusRepairValidation.Points(first.skin);foreach(var pair in eyeIndices){var delta=new Vector3[mesh.vertexCount];var eye=first.skin.bones[pair.Value];int moved=0;for(int i=0;i<delta.Length;i++){float w=weight(weights[i],pair.Value);if(w<.55f)continue;float height=Vector3.Dot(points[i]-eye.position,first.transform.up);delta[i]=first.skin.transform.InverseTransformVector(-first.transform.up*height*.94f);moved++;}if(moved<20)throw new Exception("Missing eyelid closure vertices");mesh.AddBlendShapeFrame(pair.Key.EndsWith("L")?"BlinkLeft":"BlinkRight",100,delta,null,null);}
 var saved=AssetDatabase.LoadAssetAtPath<Mesh>(folder+"DolphinEyes.asset");if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}else {saved=mesh;AssetDatabase.CreateAsset(saved,folder+"DolphinEyes.asset");}
 var material=AssetDatabase.LoadAssetAtPath<Material>(folder+"DolphinEyes.mat");if(!material){material=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(material,folder+"DolphinEyes.mat");}material.color=new Color(.019f,.014f,.009f);material.SetFloat("_Metallic",0);material.SetFloat("_Glossiness",.38f);EditorUtility.SetDirty(material);foreach(var driver in drivers){var bodyMat=driver.skin.sharedMaterial;driver.skin.sharedMesh=saved;driver.skin.sharedMaterials=new[]{bodyMat,material};}
 }
 public static void CapturePosed(Camera cam,SkinnedMeshRenderer skin,string path){
 var mesh=UnityEngine.Object.Instantiate(skin.sharedMesh);mesh.vertices=OctopusRepairValidation.Points(skin);mesh.ClearBlendShapes();var source=skin.sharedMesh;var normals=source.normals;var tangents=source.tangents;var weights=source.boneWeights;var matrices=skin.bones.Select((b,i)=>b.localToWorldMatrix*source.bindposes[i]).ToArray();for(int i=0;i<normals.Length;i++){var n=normals[i];var t=new Vector3(tangents[i].x,tangents[i].y,tangents[i].z);var w=weights[i];normals[i]=(matrices[w.boneIndex0].MultiplyVector(n)*w.weight0+matrices[w.boneIndex1].MultiplyVector(n)*w.weight1+matrices[w.boneIndex2].MultiplyVector(n)*w.weight2+matrices[w.boneIndex3].MultiplyVector(n)*w.weight3).normalized;var world=(matrices[w.boneIndex0].MultiplyVector(t)*w.weight0+matrices[w.boneIndex1].MultiplyVector(t)*w.weight1+matrices[w.boneIndex2].MultiplyVector(t)*w.weight2+matrices[w.boneIndex3].MultiplyVector(t)*w.weight3).normalized;tangents[i]=new Vector4(world.x,world.y,world.z,tangents[i].w);}mesh.normals=normals;mesh.tangents=tangents;mesh.RecalculateBounds();var go=new GameObject("Temporary baked pose for editor capture");go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;skin.enabled=false;ReefCorrectionAudit.Capture(cam,path);skin.enabled=true;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(mesh);
 }
 public static void CheckAndCapture(){Validate();Capture();}
 public static void ValidateSolo(){
 EditorSceneManager.OpenScene(Scene);var actors=Actors();var first=actors[0];foreach(var other in actors.Skip(1))UnityEngine.Object.DestroyImmediate(other.gameObject);var d=first.GetComponent<DolphinSwimController>();d.pod=new[]{d};float distance=0;for(int f=0;f<900;f++){var before=first.transform.position;first.Step(.05f);first.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();distance+=(first.transform.position-before).magnitude;if(!first.GetComponent<ReefSphereBody>().Clear(first.transform.position))throw new Exception("Solitary dolphin collision");if(d.Mode!=DolphinSwimController.SwimMode.Independent)throw new Exception("Single dolphin requested a pod formation");}if(distance<10)throw new Exception("Solitary dolphin stalled");File.WriteAllText(Output+"SoloValidation.txt","One dolphin with no peers: 45-second collision-clear independent patrol; travel="+distance+" m.\n");EditorSceneManager.OpenScene(Scene);
 }
 public static void CompleteProof(){Validate();ValidateSolo();DolphinLiveSyncCheck.Run();}
}
}







